// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // call Initialized to lock the setup
        c.Initialized();
        // In P, SetMinSum would fail after Initialized; in M it would succeed.
        // So simulate the M bug: call SetMinSum (both contracts allow calling but P reverts)
        // We need to distinguish: we'll call SetMinSum and observe if MinSum changed.
        // First check MinSum is 0
        assertEq(c.MinSum(), 0);
        // Now try setting MinSum to 1
        c.SetMinSum(1);
        // In P (with revert) this should do nothing, MinSum remains 0
        // In M (without revert) MinSum becomes 1
        // Check the final MinSum
        assertTrue(c.MinSum() == 1); // This assertion passes on M (buggy) and fails on P (reference)
    }
}

