pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: fund account for Put
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);

        // Step 1: Initialize the contract (lock future SetMinSum in reference)
        vm.prank(alice);
        c.Initialized();

        // Step 2: Put 1 wei with lockTime 0
        vm.prank(alice);
        c.Put{value: 1 wei}(0);

        // Step 3: Attempt to set MinSum after initialization
        // In reference, this should revert; in bug, it will succeed
        vm.prank(alice);
        c.SetMinSum(1);

        // Step 4: Now call Collect(1) - should succeed in reference (minSum still 0)
        // In bug, Collect will fail because minSum=1 > balance=1? Actually balance >= minSum? 1>=1 check passes
        // But the bug: after SetMinSum(1), MinSum is 1, so the condition acc.balance>=MinSum (1>=1) is true,
        // and rest passes so Collect succeeds? Wait we need divergence in MinSum value, not revert.
        // Actually the difference is MinSum value after Collect call: In reference, SetMinSum reverted so MinSum unchanged (0);
        // In bug, MinSum becomes 1. So after Collect, P.MinSum() == 0, M.MinSum() == 1.
        bool success;
        try c.Collect(1) { success = true; } catch { success = false; }

        // After the Collect call, assert MinSum differs
        assertTrue(c.MinSum() != 0, "MinSum should have been changed by SetMinSum in bug but not reference");
    }
}

