pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 so Collect threshold is low
        c.SetMinSum(1);
        // Deploy Log contract and set it
        address logAddr = address(new Log());
        c.SetLogFile(logAddr);
        // Initialize the contract (sets intitalized = true in reference)
        c.Initialized();
        // Now Put and Collect to trigger state change; warp to make unlock time pass
        vm.deal(address(this), 1);
        vm.warp(1); // so block.timestamp > 0
        c.Put(0); // deposit 1 wei, unlockTime = block.timestamp + 0 = 1, balance = 1
        vm.warp(2); // now block.timestamp = 2 > unlockTime = 1
        // Attempt Collect(1) — this will succeed (balance >= MinSum, balance >= 1, time > unlockTime)
        c.Collect(1);
        // After all this, the correct contract has initialized=true, buggy has false.
        // Test: in the correct contract, calling Put() (via fallback) after Initialized() reverts because nonReentrant + initialized guard? No, nonReentrant only locks reentrancy, the initialized check is separate.
        // Actually: SetMinSum and SetLogFile and Initialized can only be called once because of the `if(intitalized)revert();` guard. So after Initialized() is called (reference sets it), any further call to SetMinSum should revert. In bug, since intitalized never set, SetMinSum again would not revert.
        // So we try to call SetMinSum(2) and see if it reverts or not.
        // In reference: reverts because intitalized is true.
        // In bug: does not revert because intitalized is false.
        bool ok;
        try c.SetMinSum(2) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "SetMinSum should revert after Initialized, but it didn't");
    }
}

