contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 1 ether);
        // Set MinSum to 0 so that any balance meets it
        c.SetMinSum(0);
        // Initialize (should set intitalized to true in reference, false in bug)
        c.Initialized();
        // Now call Initialized again to see if we can detect difference via a later revert?
        // Actually, to exploit: Initialized() in reference sets to true (can't call again due to revert on second call?)
        // But the function doesn't check intitalized before setting; it only checks in SetMinSum/SetLogFile.
        // So we can call Initialized() many times; that's not the issue.
        // The issue: Collect() doesn't check intitalized, so no revert difference there.
        // But the property says after Collect completes, intitalized differs (P true, M false).
        // However, Collect doesn't change intitalized! So the only way is if Collect somehow indirectly changes it?
        // No. So this scenario does not produce observable divergence.
        // Let's reconsider: The mutant changes Initialized() to set false instead of true.
        // Then any later call to SetMinSum or SetLogFile will behave differently because they check intitalized.
        // So use that: after Initialized(), call SetMinSum (should revert in reference if intitalized==true, not revert in bug).
        // But the problem says the divergence is via Collect... Wait, the statement: "Driven through the public/external entry `Collect(uint256)`, P and M differ". This might mean the difference is observable after calling Collect, not necessarily that Collect changes it. 
        // But Collect doesn't touch intitalized, so the only way to observe a difference in intitalized after Collect is if intitalized was already different before Collect. 
        // And that difference was created by calling Initialized() and then maybe some other call that reverts depending on intitalized? SetMinSum reverts if intitalized true. So after Initialized(), calling SetMinSum in reference reverts, in bug does not, so after that, the state could differ.
        // Let's construct that: after Initialized(), call SetMinSum(0). In reference it reverts, so MinSum stays 0 (set earlier). In bug it doesn't revert, MinSum becomes 0 again (no change). Then intitalized? unchanged. Not helpful.
        // Another: Collect has a condition that checks MinSum, but that's set earlier. 
        // Maybe the trick is to use reentrancy? Or to call Initialized() after some condition? 
        // Let's think differently: The description says "after a call to Collect(...) completes, the value of state variable Initialized differs". That means Collect itself changes intitalized? No, it doesn't. So the only possibility is that Collect triggers a fallback that calls another function that changes intitalized? The fallback calls Put(0), not change intitalized. 
        // But there is a reentrancy guard (nonReentrant_) that could change locked_ but not intitalized. 
        // So maybe the scenario is simply: call Initialized() once, then call Collect with values that meet conditions. After Collect returns, the reference has intitalized true, bug has false (because Initialized() was called once). That's observable by reading the getter. 
        // That's what the previous approaches tried. But the hint says those were already tried and fail. 
        // But that's exactly what we need: a concrete sequence that makes the getter differ. Let's just do that.
        // So: call Initialized() once, then call Collect(0) with an account that has balance >= MinSum (0) and passed unlockTime. The reference's intitalized will be true, bug's false. After the Collect call, check c.intitalized(). That should be true for reference, false for bug.
        // That is a valid test. The compiler error earlier was due to typo "intitalized". So we can just use that.
        // But wait: the property says "Driven through the public/external entry `Collect(uint256)`" meaning the point where they diverge is after a Collect call. So we must make a Collect call, and then check intitalized. That's exactly what we do.
        // However, previous attempts say this doesn't work. But why? Because the getter is auto-generated, so it works. The error earlier was "intitalized" misspelled. It should be "intitalized" not "initialized". The contract uses "intitalized" (missing the 'i'). So we must use that spelling.
        // Let's write the test accordingly.
        // But to avoid reverts, we need to ensure Collect does not revert. 
        // Steps:
        // - Set MinSum to 0
        // - Give alice some balance and warp time so unlock time passes
        // - alice sends ether to c via fallback (so she has balance > 0)
        // - then call Initialized()
        // - then call Collect(0) from alice (she meets conditions)
        // - then check intitalized
        // That should work.
        c.SetMinSum(0);
        // Give alice ether
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        // send ether to trigger fallback -> Put(0)
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "send failed");
        // warp past unlock time (Put sets unlock to now+0, so any future time works)
        vm.warp(block.timestamp + 1);
        // Now call Initialized()
        c.Initialized();
        // Now call Collect(0) from alice
        vm.prank(alice);
        c.Collect(0);
        // Now check intitalized
        // In reference, after Initialized(), intitalized becomes true. In bug, it becomes false.
        // Collect doesn't change it, so after Collect, the difference persists.
        assertTrue(c.intitalized());
    }
